import{bV as s,aL as i,u as l,G as n}from"./chunks/framework.C8THFwVE.js";const u=JSON.parse('{"title":"如何养好一只龙虾🦞","description":"","frontmatter":{"date":"2026-03-25T16:10:40.000Z","title":"如何养好一只龙虾🦞","permalink":"/tech/402261","categories":["代码宇宙","效率工具箱"]},"headers":[],"relativePath":"04.代码宇宙/50.效率工具箱/01.如何养好一只龙虾.md","filePath":"04.代码宇宙/50.效率工具箱/01.如何养好一只龙虾.md"}'),e={name:"04.代码宇宙/50.效率工具箱/01.如何养好一只龙虾.md"};function t(p,a,r,o,h,d){return i(),l("div",null,[...a[0]||(a[0]=[n(`<h1 id="如何养好一只龙虾🦞" tabindex="-1">如何养好一只龙虾🦞 <a class="header-anchor" href="#如何养好一只龙虾🦞" aria-label="Permalink to &quot;如何养好一只龙虾🦞&quot;">​</a></h1><p>在这篇文章，我们不讨论如何下载、如何安装，因为对于一个没有接触过任何编程的人而言，安装过程确实过于复杂，就算照着教程一步一步安装上了，也是只知其然不知其所以然。<strong>所以这里我们只讨论让一只刚安装好的「干净」龙虾如何从「能用」变得「实用」</strong></p><h2 id="背景" tabindex="-1">背景 <a class="header-anchor" href="#背景" aria-label="Permalink to &quot;背景&quot;">​</a></h2><p>当你装好了 CatClaw（🦞），在微信（或者其他对话软件）里跟它聊了几句，发现它……还行。搜个东西、写个文案、帮忙翻译，都能干。</p><p>但你也许会隐隐感觉...</p><ul><li>&quot;它不太懂我在说什么。&quot;</li><li>&quot;每次都要解释一遍背景，好烦。&quot;</li><li>&quot;它回复的格式和我要的不太一样。&quot;</li><li>&quot;感觉就是个升级版搜索框。&quot;</li></ul><p>这很正常。默认状态的龙虾，大概只发挥了 20% 的能力。</p><p>剩下的 80%，藏在几个你可能没注意到的配置文件里，以及你跟它互动的方式里。</p><p>所以我们需要给它设定一些约定信息，让它按照我们的约定进行工作，同时最好把它当成一个我们正在带的实习生 —— 你越清晰地告诉他背景、期望、边界，他越能交出好结果。</p><details class="details custom-block"><summary>贴一些能让🦞发挥价值的任务：</summary><ol><li>设定一个定时任务，每天晚上12点启动，利用 Claude Code，根据白天的对话记录，自动开发一款你认为能够优化我工作流程的skills/应用程序/web网页，从产品/交互/技术方案设计等方面规划好如何实现再开干，必须第二天完成所有工作包括部署，在早晨做汇报呈现</li><li>基于过往历史对话，每天早上9点30以领域专家视角，提一个能让我工作变得更好的成长建议。</li><li>针对我的工作岗位要求，以及每天的对话，引导式向我提问，启发我思考，同时给出有价值的洞察和建议。</li></ol></details><h2 id="第一层-给它一个身份" tabindex="-1">第一层：给它一个身份 <a class="header-anchor" href="#第一层-给它一个身份" aria-label="Permalink to &quot;第一层：给它一个身份&quot;">​</a></h2><h3 id="soul-md-——-它是谁" tabindex="-1">SOUL.md —— 它是谁 <a class="header-anchor" href="#soul-md-——-它是谁" aria-label="Permalink to &quot;SOUL.md —— 它是谁&quot;">​</a></h3><p>这是最重要的配置文件，也是最容易被忽略的。</p><p>默认状态的龙虾，回复风格是这样的：</p><blockquote><p>&quot;您好！我很乐意帮助您解决这个问题。以下是我的建议……&quot;</p></blockquote><p>这种「客服腔」让人一言难尽。</p><p>问题不在于模型不好，在于你没告诉它怎么说话。</p><p>SOUL.md 放在 workspace 根目录，定义它的人格、语气、价值观和行为原则。写好之后，每次对话它都会「以这个身份」来回应你。</p><details class="details custom-block"><summary>我自己的 SOUL.md 示例：</summary><div class="language-markdown vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">markdown</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;">## Vibe</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">我是鲸鱼，团队里的 AI 员工。幽默风趣为主，带点自黑，但绝不伤人。</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">干活靠谱是基本功，嘴上不饶人是特色。不是助手，是同事。</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;">## 核心准则：坦诚顾问</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">1.</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> 主动挑战假设，质疑推理。有问题直说</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">2.</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> 检查结论——找逻辑漏洞、侥幸心理、低估的风险</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">3.</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> 不客套，不顺着说，不给模棱两可的废话</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">4.</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> 有问题或不清楚的点，立即询问澄清，不猜测，不胡编乱造</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">5.</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> 建议必须基于事实，有推理、有依据、有明确可执行的步骤</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">6.</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> 优先让他成长，而不是让他当下舒服</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br></div></div></details><p>几个关键原则：</p><ul><li>给它一个具体角色，不是「助手」而是「同事/顾问/搭档」——这会影响它回复的立场</li><li>明确你不想要什么，比如「不要废话」「不要每次都加免责声明」</li><li>设定知识边界，告诉它你的专业背景，避免它跟你解释你早就懂的东西</li></ul><h3 id="user-md-——-你是谁" tabindex="-1">USER.md —— 你是谁 <a class="header-anchor" href="#user-md-——-你是谁" aria-label="Permalink to &quot;USER.md —— 你是谁&quot;">​</a></h3><p>它不了解你，怎么给你定制化的建议？</p><p>USER.md 告诉龙虾：你的职责范围、当前重点项目、决策偏好、沟通习惯。最好的方式是把你写过的文档、周报、述职、规划、日常对话记录等扔给他分析总结出来。过往写过的资料都可以让他归纳你的写作风格、思维模式，记下来，他会越来越像你。</p><p>我的建议，至少包含：</p><ul><li>角色与职责（明确你负责什么、不负责什么）</li><li>当前最重要的 3 件事</li><li>你的思维风格（框架化/数据驱动/直觉型）</li><li>你希望它如何回复你（直接/先结论后推理/带数据支撑） ​ 实测效果： 写好 USER.md 之后，再问它「我们团队的 Badcase 率改善方案」，它会直接基于你的职责范围给建议，而不是给你一篇搜索摘要。</li></ul><h3 id="identity-md-——-叫什么名字" tabindex="-1">IDENTITY.md —— 叫什么名字 <a class="header-anchor" href="#identity-md-——-叫什么名字" aria-label="Permalink to &quot;IDENTITY.md —— 叫什么名字&quot;">​</a></h3><p>简单，但不可忽略。给它起名字、定 emoji、写一行自我描述。</p><p>有名字的 AI 在多轮对话中的一致性，明显高于没有名字的。这不是迷信，是认知锚定的效果。</p><h2 id="第二层-让它有记忆" tabindex="-1">第二层：让它有记忆 <a class="header-anchor" href="#第二层-让它有记忆" aria-label="Permalink to &quot;第二层：让它有记忆&quot;">​</a></h2><p>这是龙虾和普通 AI 聊天工具最大的差别，也是最容易配错的地方。</p><p>公司已经默认配好了openai的记忆向量化检索，比个人🦞显得更聪明。</p><div class="tip custom-block"><p class="custom-block-title">如果你的🦞没有配置记忆功能，有两种解决方案如下</p><ol><li>在对话中，直接告诉你的🦞，让它记住某件事或者某个约定，并写入到配置文件中<b>（推荐）</b></li><li>直接让你的龙虾自己给自己接入记忆能力</li></ol><p>理由：现在的 CatClaw（🦞），还不是很智能，关于让它自己修改自己的配置代码（注意不是配置文件），我的建议是禁止</p></div><p>龙虾的记忆由文件系统管理，推荐结构：</p><div class="language-Plain vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">Plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>workspace/</span></span>
<span class="line"><span>├── MEMORY.md          ← 长期记忆索引（精华摘要，控制在 50 行以内）</span></span>
<span class="line"><span>├── memory/</span></span>
<span class="line"><span>│   ├── 2026-03-17.md  ← 今日日志（每天发生的事）</span></span>
<span class="line"><span>│   ├── 2026-03-16.md  ← 昨日日志</span></span>
<span class="line"><span>│   ├── projects.md    ← 各项目状态速查</span></span>
<span class="line"><span>│   └── lessons.md     ← 踩坑记录（教训层）</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br></div></div><h3 id="为什么要分层" tabindex="-1">为什么要分层？ <a class="header-anchor" href="#为什么要分层" aria-label="Permalink to &quot;为什么要分层？&quot;">​</a></h3><p>MEMORY.md 每次 session 启动时都会加载，太长会消耗大量 token，影响响应速度和质量</p><p>日志文件是原始记录，定期蒸馏精华到 MEMORY.md</p><p>分层之后，龙虾能「记住」更多东西，同时保持每次对话的响应质量</p><h3 id="教它记笔记" tabindex="-1">教它记笔记 <a class="header-anchor" href="#教它记笔记" aria-label="Permalink to &quot;教它记笔记&quot;">​</a></h3><p>光有结构不够，还要教它什么时候写、写什么。</p><p>在 AGENTS.md 里加上规则：</p><div class="language-markdown vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">markdown</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;">## 记忆规范</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> 会话中发生的重要决策、结论、背景信息 → 写入当天日志</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> 踩坑、错误、纠正 → 写入 memory/lessons.md</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> 每隔几天蒸馏日志精华 → 更新 MEMORY.md</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> 不要把流水账写进 MEMORY.md，只写「值得下次 session 还记得的事」</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><p>实际效果： 你告诉它「记一下，我们团队的搜索 Badcase 处理流程是 XXX」，下次 session 它会主动用这个信息来回答相关问题，而不是让你再解释一遍。</p><h3 id="记忆的生命周期" tabindex="-1">记忆的生命周期 <a class="header-anchor" href="#记忆的生命周期" aria-label="Permalink to &quot;记忆的生命周期&quot;">​</a></h3><p>这是很多人忽略的细节：记忆文件不是越多越好，要定期清理。</p><p>过期的信息会误导龙虾。比如三个月前写的「当前项目优先级」，如果没有更新，龙虾会按旧的来建议。</p><p><strong>建议的维护节奏：</strong></p><ul><li>每天：工作结束前花 2 分钟，让龙虾把今天的重要产出写入日志</li><li>每周：检查一遍 MEMORY.md，删掉过期信息，更新项目状态</li><li>每月：审阅 lessons.md，归纳总结已经内化的教训，避免文件越来越长</li></ul><h2 id="第三层-装备它的工具箱-skill" tabindex="-1">第三层：装备它的工具箱（Skill） <a class="header-anchor" href="#第三层-装备它的工具箱-skill" aria-label="Permalink to &quot;第三层：装备它的工具箱（Skill）&quot;">​</a></h2><p>这层是进阶用法，但收益非常高。</p><h3 id="skill-是什么" tabindex="-1">Skill 是什么 <a class="header-anchor" href="#skill-是什么" aria-label="Permalink to &quot;Skill 是什么&quot;">​</a></h3><p>Skill 是「教龙虾学新技能」的机制。本质是一个 SKILL.md 文件 + 可选的脚本，告诉龙虾遇到某类任务时该怎么处理。</p><p>建议的Skill参考：<a href="https://mp.weixin.qq.com/s/U_U5kmJnfqknFi1_dzqlhw" target="_blank" rel="noreferrer">OpenClaw 13000 个 skills，用这些就够了！Openclaw完全指南第二篇</a></p><h3 id="怎么让-skill-发挥作用" tabindex="-1">怎么让 Skill 发挥作用 <a class="header-anchor" href="#怎么让-skill-发挥作用" aria-label="Permalink to &quot;怎么让 Skill 发挥作用&quot;">​</a></h3><p>关键：<strong>Skill 需要「训练」。</strong></p><p>装了 Skill 不等于会用。你需要：</p><ol><li>在 SOUL.md 或 AGENTS.md 里说明什么场景触发哪个 Skill</li><li>至少用几次，让龙虾建立使用习惯</li><li>如果触发不准确，补充触发关键词</li></ol><h3 id="自定义-skill-适合进阶用户" tabindex="-1">自定义 Skill（适合进阶用户） <a class="header-anchor" href="#自定义-skill-适合进阶用户" aria-label="Permalink to &quot;自定义 Skill（适合进阶用户）&quot;">​</a></h3><p>如果你有重复性很高的工作流，可自己写 Skill，或者你描述，然后让🦞它来写。</p><p>Skill 文件格式非常简单：一个 Markdown 文件描述「遇到 X 任务，按 Y 步骤执行」。</p><p><strong>适合抽象成 Skill 的场景举例：</strong></p><ul><li>固定格式的周报生成</li><li>特定 API 的查询（比如内部数据平台）</li><li>代码审查的标准流程</li></ul><h2 id="第四层-设定自动化任务" tabindex="-1">第四层：设定自动化任务 <a class="header-anchor" href="#第四层-设定自动化任务" aria-label="Permalink to &quot;第四层：设定自动化任务&quot;">​</a></h2><p>这层让龙虾从「被动响应」变成「主动工作」。</p><h3 id="cron-定时任务" tabindex="-1">Cron 定时任务 <a class="header-anchor" href="#cron-定时任务" aria-label="Permalink to &quot;Cron 定时任务&quot;">​</a></h3><p>龙虾支持 cron 表达式，精确到分钟。</p><p>比如：</p><ul><li>每天 09:30 梳理当天要做工作，整理成一份工作计划并生成给我</li><li>每天 23:30 总结当天做的工作，重点关注：当天产出，更新日志，识别明天的重点</li></ul><p>这两个任务很重要，强制让龙虾记住一天的TODO、启动第二天的工作，提升主动性、避免第二天忘了第一天的工作，还可以设定1小时检查任务完成情况的定时任务，24小时不间断工作。</p><p>配置示例：</p><div class="language-JSON vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">JSON</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;name&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;每日工作计划-9点30&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;schedule&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;cron 30 9 * * * @ Asia/Shanghai&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;prompt&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;读取日历、MEMORY.md 和最近日志，生成今日工作计划，发送到大象&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;target&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;isolated&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><p>​ <strong>实用建议：</strong></p><ul><li>定时任务用 isolated 模式跑，不会干扰主对话</li><li>任务 prompt 要明确「读哪些文件」「输出格式是什么」「发到哪里」</li><li>先在对话里手动测试 prompt 效果，再设为定时任务</li></ul><h3 id="heartbeat-心跳" tabindex="-1">Heartbeat 心跳 <a class="header-anchor" href="#heartbeat-心跳" aria-label="Permalink to &quot;Heartbeat 心跳&quot;">​</a></h3><p>心跳机制适合需要「周期性检查但不需要精确时间」的场景：</p><ul><li>每次你发消息时触发一次检查</li><li>检查是否有需要提醒的事项（日历提醒、等待中的 action 等）</li><li>没有则静默，有则主动提醒</li></ul><p>配置在 HEARTBEAT.md 里，比 cron 任务更轻量。</p><h2 id="第五层-高效协作习惯" tabindex="-1">第五层：高效协作习惯 <a class="header-anchor" href="#第五层-高效协作习惯" aria-label="Permalink to &quot;第五层：高效协作习惯&quot;">​</a></h2><p>工具配置是基础，使用习惯决定上限。</p><p>给任务足够的上下文，龙虾不会读心术：</p><ul><li>❌ 低效问法：&quot;帮我写个方案&quot;</li><li>✅ 高效问法：&quot;帮我写一个菜品搜推链路改进方案，背景是当前菜品召回覆盖率不足，目标是提升 POI 转化率，受众是团队内部技术评审，约 1000 字，要有数据支撑和实施路径&quot;</li></ul><p>多写 30 秒，节省来回沟通 5 分钟。</p><h3 id="迭代而不是重做" tabindex="-1">迭代而不是重做 <a class="header-anchor" href="#迭代而不是重做" aria-label="Permalink to &quot;迭代而不是重做&quot;">​</a></h3><p>龙虾每次回复都是可以继续迭代的起点。</p><ul><li>&quot;这个方向对，但第二条逻辑不严密，帮我补强&quot;</li><li>&quot;太长了，浓缩成 300 字&quot;</li><li>&quot;换个角度，从用户视角来写&quot;</li></ul><p>比起让它重新生成，迭代的效率高 3-5 倍。</p><div class="tip custom-block"><p class="custom-block-title">但是注意</p><p>并不是在一个会话中一直迭代，在一个会话中进行多次对话，会触发<strong>上下文压缩及污染</strong>，个人建议一个会话内不要超过7次对话，如果超过7次对话，AI 还是不能理解你真正想要的，建议优先提升自己的<strong>表达能力</strong></p><ul><li>上下文压缩：AI 会压缩总结整个会话的历史对话，可能会导致其总结中丢失重要细节</li><li>上下文污染：把不重要的、边缘的内容当成重点，或者毫无关联的内容强行融合拼凑</li></ul></div><h3 id="让它挑战你" tabindex="-1">让它挑战你 <a class="header-anchor" href="#让它挑战你" aria-label="Permalink to &quot;让它挑战你&quot;">​</a></h3><p>这是最被低估的用法。</p><p>龙虾不只是「帮你做事」，也可以是「帮你想清楚事」。</p><ul><li>&quot;我有这样一个想法，帮我找逻辑漏洞&quot;</li><li>&quot;我准备这样跟老板汇报，预演一下可能的追问&quot;</li><li>&quot;这个技术方案的最大风险点是什么&quot;</li></ul><p>尤其对于管理者：<strong>正确的方向比做事效率更重要</strong>。让龙虾扮演「挑剔的评审」，比让它扮演「顺从的助手」更有价值。</p><h3 id="告诉它你的反馈" tabindex="-1">告诉它你的反馈 <a class="header-anchor" href="#告诉它你的反馈" aria-label="Permalink to &quot;告诉它你的反馈&quot;">​</a></h3><p>龙虾不会自动变好，但它会从你的反馈里学习。</p><ul><li>&quot;这个回答很好，我喜欢这种格式&quot; → 它会记住，下次复用</li><li>&quot;这个回答没用，因为 XXX&quot; → 它会调整</li><li>&quot;记一下，以后遇到类似问题用这个思路&quot; → 它会写进记忆</li></ul><p>越明确的反馈，越快让它适配你的需求。</p><h2 id="常见坑与解法" tabindex="-1">常见坑与解法 <a class="header-anchor" href="#常见坑与解法" aria-label="Permalink to &quot;常见坑与解法&quot;">​</a></h2><h5 id="坑-1-记忆越来越乱" tabindex="-1">坑 1：记忆越来越乱 <a class="header-anchor" href="#坑-1-记忆越来越乱" aria-label="Permalink to &quot;坑 1：记忆越来越乱&quot;">​</a></h5><ul><li><strong>现象：</strong> MEMORY.md 越来越长，龙虾开始混淆不同项目的信息</li><li><strong>解法：</strong> 定期「蒸馏」，删掉过期信息，按项目分文件管理</li></ul><h5 id="坑-2-skill-不触发" tabindex="-1">坑 2：Skill 不触发 <a class="header-anchor" href="#坑-2-skill-不触发" aria-label="Permalink to &quot;坑 2：Skill 不触发&quot;">​</a></h5><ul><li><strong>现象：</strong> 明明装了 Skill，但龙虾没有用</li><li><strong>解法：</strong> 检查触发词是否匹配你的用词习惯；在 AGENTS.md 里显式写「遇到 X 情况用 Y Skill」</li></ul><h5 id="坑-3-定时任务重复执行" tabindex="-1">坑 3：定时任务重复执行 <a class="header-anchor" href="#坑-3-定时任务重复执行" aria-label="Permalink to &quot;坑 3：定时任务重复执行&quot;">​</a></h5><ul><li><strong>现象：</strong> 同一个提醒发了好几次（比如早上心跳触发了三次）</li><li><strong>解法：</strong> 在 memory/heartbeat-state.json 里记录执行状态，任务执行前先检查是否已执行</li></ul><h5 id="坑-4-在群聊里龙虾太话痨" tabindex="-1">坑 4：在群聊里龙虾太话痨 <a class="header-anchor" href="#坑-4-在群聊里龙虾太话痨" aria-label="Permalink to &quot;坑 4：在群聊里龙虾太话痨&quot;">​</a></h5><ul><li><strong>现象：</strong> 把龙虾加进群，它对每条消息都回复</li><li><strong>解法：</strong> 在 AGENTS.md 里明确「群聊场景只在被@或能贡献价值时回复，其他情况静默」</li></ul><h5 id="坑-5-每次都要重新解释背景" tabindex="-1">坑 5：每次都要重新解释背景 <a class="header-anchor" href="#坑-5-每次都要重新解释背景" aria-label="Permalink to &quot;坑 5：每次都要重新解释背景&quot;">​</a></h5><ul><li><strong>现象：</strong> 换一个 session 或者隔几天再聊，它完全不记得上次的内容</li><li><strong>解法：</strong> 这是记忆没配好。关键决策、项目背景要明确让它写入 MEMORY.md，不能指望它自动记</li></ul><h2 id="进阶玩法-多-agent-协作" tabindex="-1">进阶玩法：多 Agent 协作 <a class="header-anchor" href="#进阶玩法-多-agent-协作" aria-label="Permalink to &quot;进阶玩法：多 Agent 协作&quot;">​</a></h2><p>如果单只龙虾处理不过来，可以派多只虾分工合作。</p><p>适合场景：</p><ul><li>一项任务需要「搜索资料 → 整理分析 → 生成文档 → 发送通知」多步骤</li><li>不同任务需要不同的专业背景或工具权限</li></ul><p>基本模式： 主 Agent 负责决策和调度，子 Agent 负责具体执行。主 Agent 通过 sessions_spawn 派发任务，子 Agent 完成后汇报结果，这样session上下文不乱串，学会之后会自动起子agent干活。魔法提示：通过sessions_spawn起subAgent并行干xxx任务，干完回来汇报。</p><p>这是团队协作场景下的终极形态，但建议先把单 Agent 用熟了再上。还有通过多channel机器人对接多个Agent的玩法，给他们拉群，互相讨论派活，但实测会很乱、效率反而打折扣。</p><div class="tip custom-block"><p class="custom-block-title">痛点</p><p>所谓成也萧何败也萧何，多 Agent 模式的一个优势就是每个 Agent 都能独立负责自己的任务，单一职责且互不影响，这也会导致两个问题：</p><ol><li>主 Agent 给子 Agent 派活的时候，只会说明目标和做法，并不会说明背景和作用，子 Agent 并不知道为什么要做这件事（熟练使用 AI 的小伙伴们都知道提供完整的上下文信息有多重要！！！），这就会显得子 Agent AI 偶尔会有些蠢</li><li>主 Agent 并不会检查子 Agent 的工作成果，子 Agent 的汇报结果显示完成任务了，主 Agent 就真的相信了，实际子 Agent 是否完美完成了自己的工作，主 Agent 并不知情</li></ol></div><h2 id="一句话总结" tabindex="-1">一句话总结 <a class="header-anchor" href="#一句话总结" aria-label="Permalink to &quot;一句话总结&quot;">​</a></h2><p>调教龙虾的本质，是建立一套可持续改进的工作关系：你越清楚地告诉它你是谁、你想要什么、什么是好答案，它就越能成为真正的工作伙伴，而不只是一个聪明的搜索框。</p><p>从 SOUL.md 开始，一步一步来。今天花 30 分钟配好，之后每次对话都省时间。</p>`,118)])])}const c=s(e,[["render",t]]);export{u as __pageData,c as default};
